342	new file mode 100644
343	index 0000000..67386cc
344	--- /dev/null
345	+++ b/src/main/java/hotel/reservations/WeekendPackagePlan.java
346	@@ -0,0 +1,44 @@
347	+package hotel.reservations;
348	+
349	+import hotel.rooms.Room;
350	+import hotel.rooms.RoomType;
351	+import java.math.BigDecimal;
352	+import java.time.DayOfWeek;
353	+import java.time.LocalDate;
354	+import java.time.temporal.ChronoUnit;
355	+import java.util.Map;
356	+
357	+final class WeekendPackagePlan implements RatePlanStrategy {
358	+
359	+    private static final Map<RoomType, BigDecimal> PACKAGE_PRICES = Map.of(
360	+            RoomType.STANDARD, new BigDecimal("520.00"),
361	+            RoomType.DELUXE, new BigDecimal("820.00"),
362	+            RoomType.SUITE, new BigDecimal("1200.00"));
363	+
364	+    @Override
365	+    public void validate(NewReservation request, Room room) {
366	+        if (request.checkIn().getDayOfWeek() != DayOfWeek.FRIDAY) {
367	+            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package requires check-in on Friday");
368	+        }
369	+        if (request.checkOut().getDayOfWeek() != DayOfWeek.SUNDAY) {
370	+            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package requires check-out on Sunday");
371	+        }
372	+        long nights = ChronoUnit.DAYS.between(request.checkIn(), request.checkOut());
373	+        if (nights != 2) {
374	+            throw new HotelException(ErrorCode.INVALID_REQUEST, "weekend package is exactly 2 nights (Friday to Sunday)");
375	+        }
376	+    }
377	+
378	+    @Override
379	+    public BigDecimal calculateDiscount(
380	+            BigDecimal subtotal, NewReservation request, Room room, LocalDate checkIn, LocalDate checkOut) {
381	+        // Package has fixed price, so discount = subtotal - package price
382	+        BigDecimal packagePrice = PACKAGE_PRICES.get(room.type());
383	+        return PriceCalculator.cents(subtotal.subtract(packagePrice));
384	+    }
385	+
386	+    @Override
387	+    public BigDecimal refundAmount(BigDecimal amountPaid) {
388	+        return PriceCalculator.cents(amountPaid.divide(new BigDecimal("2")));
389	+    }
390	+}
