  1	package hotel.reservations;
  2	
  3	import hotel.documents.ReservationReceipt;
  4	import hotel.messages.EmailSender;
  5	import hotel.rooms.Room;
  6	import hotel.rooms.Rooms;
  7	import java.math.BigDecimal;
  8	
  9	/** The life of a reservation: created, confirmed (paid), checked in, checked out, or cancelled. */
 10	public final class ReservationService {
 11	
 12	    static final String HOTEL_NAME = "Pousada Maré Alta";
 13	
 14	    private final Rooms rooms;
 15	    private final ReservationStore store;
 16	    private final PriceCalculator priceCalculator;
 17	    private final EmailSender emailSender;
 18	
 19	    public ReservationService(
 20	            Rooms rooms, ReservationStore store, PriceCalculator priceCalculator, EmailSender emailSender) {
 21	        this.rooms = rooms;
 22	        this.store = store;
 23	        this.priceCalculator = priceCalculator;
 24	        this.emailSender = emailSender;
 25	    }
 26	
 27	    public synchronized Reservation create(NewReservation request) {
 28	        if (!request.checkOut().isAfter(request.checkIn())) {
 29	            throw new HotelException(ErrorCode.INVALID_REQUEST, "check-out must be after check-in");
 30	        }
 31	        if (request.guests() < 1) {
 32	            throw new HotelException(ErrorCode.INVALID_REQUEST, "a reservation needs at least one guest");
 33	        }
 34	        Room room = rooms.find(request.roomNumber())
 35	                .orElseThrow(() -> new HotelException(
 36	                        ErrorCode.ROOM_NOT_FOUND, "room " + request.roomNumber() + " does not exist"));
 37	        if (request.guests() > room.capacity()) {
 38	            throw new HotelException(
 39	                    ErrorCode.CAPACITY_EXCEEDED,
 40	                    "room " + room.number() + " takes at most " + room.capacity() + " guests");
 41	        }
 42	        RatePlanStrategy strategy = RatePlanStrategies.strategyFor(request.ratePlan());
 43	        strategy.validate(request, room);
 44	        if (store.isRoomTaken(room.number(), request.checkIn(), request.checkOut())) {
 45	            throw new HotelException(
 46	                    ErrorCode.ROOM_UNAVAILABLE, "room " + room.number() + " is taken on some of those nights");
 47	        }
 48	        Price price = priceCalculator.calculate(room, request.checkIn(), request.checkOut(), request);
 49	        return store.add(request, price);
 50	    }
 51	
 52	    public Reservation find(long reservationId) {
 53	        return store.find(reservationId)
 54	                .orElseThrow(() -> new HotelException(
 55	                        ErrorCode.RESERVATION_NOT_FOUND, "reservation " + reservationId + " does not exist"));
 56	    }
 57	
 58	    /** The guest paid: the reservation is confirmed and the guest gets the receipt by e-mail. */
 59	    public synchronized Reservation confirm(long reservationId) {
 60	        Reservation reservation = find(reservationId);
 61	        if (reservation.status() != ReservationStatus.PENDING) {
 62	            throw notAllowed(reservation, "confirm");
 63	        }
 64	        reservation.confirmPayment();
 65	        store.update(reservation);
 66	        ReservationReceipt receipt = new ReservationReceipt(reservation, roomOf(reservation));
 67	        emailSender.send(
 68	                reservation.guest().email(),
 69	                "Reserva confirmada - " + HOTEL_NAME,
 70	                confirmationEmailBody(reservation, receipt));
 71	        return reservation;
 72	    }
 73	
 74	    /**
 75	     * Cancelling before the stay starts. What was paid comes back according to the rate plan (a pending
 76	     * reservation was never paid, so nothing comes back).
 77	     */
 78	    public synchronized Reservation cancel(long reservationId) {
 79	        Reservation reservation = find(reservationId);
 80	        if (reservation.status() != ReservationStatus.PENDING
 81	                && reservation.status() != ReservationStatus.CONFIRMED) {
 82	            throw notAllowed(reservation, "cancel");
 83	        }
 84	        RatePlanStrategy strategy = RatePlanStrategies.strategyFor(reservation.ratePlan());
 85	        BigDecimal refund = strategy.refundAmount(reservation.amountPaid());
 86	        reservation.cancel(refund);
 87	        store.update(reservation);
 88	        return reservation;
 89	    }
 90	
 91	    public synchronized Reservation checkIn(long reservationId) {
 92	        Reservation reservation = find(reservationId);
 93	        if (reservation.status() != ReservationStatus.CONFIRMED) {
 94	            throw notAllowed(reservation, "check in");
 95	        }
 96	        reservation.changeStatus(ReservationStatus.CHECKED_IN);
 97	        store.update(reservation);
 98	        return reservation;
 99	    }
100	
101	    /** The guest leaves: the stay is closed and the final receipt is handed over. */
102	    public synchronized ReservationReceipt checkOut(long reservationId) {
103	        Reservation reservation = find(reservationId);
104	        if (reservation.status() != ReservationStatus.CHECKED_IN) {
105	            throw notAllowed(reservation, "check out");
106	        }
107	        reservation.changeStatus(ReservationStatus.CHECKED_OUT);
108	        store.update(reservation);
109	        return new ReservationReceipt(reservation, roomOf(reservation));
110	    }
111	
112	    /** A copy of the receipt, for a guest who lost it. Only paid reservations have one. */
113	    public ReservationReceipt receiptCopy(long reservationId) {
114	        Reservation reservation = find(reservationId);
115	        if (!reservation.isPaid()) {
116	            throw notAllowed(reservation, "issue a receipt for");
117	        }
118	        return new ReservationReceipt(reservation, roomOf(reservation));
119	    }
120	
121	    private Room roomOf(Reservation reservation) {
122	        return rooms.find(reservation.roomNumber()).orElseThrow();
123	    }
124	
125	    private static String confirmationEmailBody(Reservation reservation, ReservationReceipt receipt) {
126	        return "Olá, " + reservation.guest().name() + "!\n\n"
127	                + "Sua reserva na " + HOTEL_NAME + " está confirmada. Estes são os dados dela:\n\n"
128	                + receipt.text() + "\n"
129	                + "A entrada é a partir das 14h, e a saída, até as 12h.\n"
130	                + "Até breve!\n";
131	    }
132	
133	    private static HotelException notAllowed(Reservation reservation, String operation) {
134	        return new HotelException(
135	                ErrorCode.OPERATION_NOT_ALLOWED,
136	                "cannot " + operation + " reservation " + reservation.id() + " while it is " + reservation.status());
137	    }
138	}
139	package hotel.reservations;
140	
141	import hotel.rooms.Room;
142	import java.math.BigDecimal;
143	import java.math.RoundingMode;
144	import java.time.LocalDate;
145	import java.time.Month;
146	
147	/**
148	 * The price of a stay: every night costs the room's nightly rate, plus the high-season surcharge on
149	 * high-season nights; the rate plan may then give a discount on the sum. Money is rounded to cents
150	 * (half-even) at every step.
151	 */
152	public final class PriceCalculator {
153	
154	    static final BigDecimal HIGH_SEASON_SURCHARGE = new BigDecimal("0.20");
155	
156	    public Price calculate(Room room, LocalDate checkIn, LocalDate checkOut, NewReservation request) {
157	        int nights = 0;
158	        BigDecimal subtotal = cents(BigDecimal.ZERO);
159	        for (LocalDate night = checkIn; night.isBefore(checkOut); night = night.plusDays(1)) {
160	            subtotal = subtotal.add(nightPrice(room, night));
161	            nights++;
162	        }
163	        RatePlanStrategy strategy = RatePlanStrategies.strategyFor(request.ratePlan());
164	        BigDecimal discount = strategy.calculateDiscount(subtotal, request, room, checkIn, checkOut);
165	        return new Price(nights, subtotal, discount, subtotal.subtract(discount));
166	    }
167	
168	    BigDecimal nightPrice(Room room, LocalDate night) {
169	        BigDecimal nightlyRate = room.nightlyRate();
170	        if (isHighSeason(night)) {
171	            return cents(nightlyRate.multiply(BigDecimal.ONE.add(HIGH_SEASON_SURCHARGE)));
172	        }
173	        return cents(nightlyRate);
174	    }
175	
176	    /** High season: from December 15 to the end of February, and the whole of July. */
177	    static boolean isHighSeason(LocalDate date) {
178	        Month month = date.getMonth();
179	        return month == Month.JANUARY
180	                || month == Month.FEBRUARY
181	                || month == Month.JULY
182	                || (month == Month.DECEMBER && date.getDayOfMonth() >= 15);
183	    }
184	
185	    static BigDecimal cents(BigDecimal value) {
186	        return value.setScale(2, RoundingMode.HALF_EVEN);
187	    }
188	}
  1	    private static int httpStatus(ErrorCode errorCode) {
  2	        return switch (errorCode) {
  3	            case INVALID_REQUEST -> 400;
  4	            case ROOM_NOT_FOUND, RESERVATION_NOT_FOUND -> 404;
  5	            case ROOM_UNAVAILABLE, OPERATION_NOT_ALLOWED -> 409;
  6	            case CAPACITY_EXCEEDED -> 422;
  7	        };
  8	    }
  9	
 10	    private static NewReservation readNewReservation(Context ctx) {
 11	        CreateReservationRequest body;
 12	        try {
 13	            body = ctx.bodyAsClass(CreateReservationRequest.class);
 14	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
 15	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
 16	        }
 17	        if (body == null
 18	                || body.roomNumber() == null
 19	                || isBlank(body.guestName())
 20	                || isBlank(body.guestEmail())
 21	                || isBlank(body.guestCpf())
 22	                || body.checkIn() == null
 23	                || body.checkOut() == null
 24	                || body.guests() == null
 25	                || body.ratePlan() == null) {
 26	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
 27	        }
 28	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
 29	        return new NewReservation(
 30	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan(),
 31	                body.companyCode());
 32	    }
 33	
 34	    private static long reservationId(Context ctx) {
 35	        String id = ctx.pathParam("id");
 36	        try {
 37	            return Long.parseLong(id);
 38	        } catch (NumberFormatException notANumber) {
 39	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
 40	        }
 41	    }

