 10	    private static NewReservation readNewReservation(Context ctx) {
 11	        CreateReservationRequest body;
 12	        try {
 13	            body = ctx.bodyAsClass(CreateReservationRequest.class);
 14	        } catch (Exception unreadableBody) { // Jackson's own exceptions are checked, but reach here unwrapped
 15	            throw new HotelException(ErrorCode.INVALID_REQUEST, "the body is not a valid reservation request");
 16	        }
 17	        if (body == null
 18	                || body.roomNumber() == null
 19	                || isBlank(body.guestName())
 20	                || isBlank(body.guestEmail())
 21	                || isBlank(body.guestCpf())
 22	                || body.checkIn() == null
 23	                || body.checkOut() == null
 24	                || body.guests() == null
 25	                || body.ratePlan() == null) {
 26	            throw new HotelException(ErrorCode.INVALID_REQUEST, "every field of the reservation is required");
 27	        }
 28	        Guest guest = new Guest(body.guestName(), body.guestEmail(), body.guestCpf());
 29	        return new NewReservation(
 30	                body.roomNumber(), guest, body.checkIn(), body.checkOut(), body.guests(), body.ratePlan(),
 31	                body.companyCode());
 32	    }
