 34	    private static long reservationId(Context ctx) {
 35	        String id = ctx.pathParam("id");
 36	        try {
 37	            return Long.parseLong(id);
 38	        } catch (NumberFormatException notANumber) {
 39	            throw new HotelException(ErrorCode.RESERVATION_NOT_FOUND, "reservation " + id + " does not exist");
 40	        }
 41	    }

